mapper.select:
SELECT

FROM users user_account

WHERE user_account.id = #{userId}
    AND user_account.is_deleted = FALSE
    AND user_account.actor_type = 'TENANT'
    AND user_account.company_id = #{companyId}

SELECT department.id
FROM departments department
WHERE department.id = #{departmentId}
    AND department.company_id = #{companyId}
    AND department.is_deleted = FALSE

SELECT EXISTS(
    SELECT 1
    FROM users user_account
    WHERE user_account.company_id IS NULL
        AND user_account.username = #{username}
)

SELECT EXISTS(
    SELECT 1
    FROM users user_account
    WHERE user_account.company_id IS NULL
        AND user_account.email = #{email}
)

SELECT EXISTS(
    SELECT 1
    FROM users user_account
    WHERE user_account.company_id = #{companyId}
        AND user_account.username = #{username}
)

SELECT EXISTS(
    SELECT 1
    FROM users user_account
    WHERE user_account.company_id = #{companyId}
        AND user_account.email = #{email}
)

SELECT EXISTS(
    SELECT 1
    FROM users user_account
    WHERE user_account.company_id IS NULL
        AND user_account.email = #{email}
        AND user_account.id != #{userId}
)

SELECT EXISTS(
    SELECT 1
    FROM users user_account
    WHERE user_account.company_id = #{companyId}
        AND user_account.email = #{email}
        AND user_account.id != #{userId}
)
